CREATE POLICY "Workspace files read" ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'sources' AND public.owns_workspace(((storage.foldername(name))[1])::uuid));
CREATE POLICY "Workspace files insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'sources' AND public.owns_workspace(((storage.foldername(name))[1])::uuid));
CREATE POLICY "Workspace files update" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'sources' AND public.owns_workspace(((storage.foldername(name))[1])::uuid));
CREATE POLICY "Workspace files delete" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'sources' AND public.owns_workspace(((storage.foldername(name))[1])::uuid));